import{_ as s,r as n,o as t,c as r,a as e,b as i,e as o,d as l}from"./app-ce950eb2.js";const c={},p=l('<h1 id="single-spa-基础" tabindex="-1"><a class="header-anchor" href="#single-spa-基础" aria-hidden="true">#</a> single-spa 基础</h1><p>single-spa 是一个将多个单页面应用聚合为一个整体应用的 JavaScript 微前端框架。</p><h2 id="实现方法" tabindex="-1"><a class="header-anchor" href="#实现方法" aria-hidden="true">#</a> 实现方法</h2><p>single-spa 提供了一种基于路由的基座化的微前端方案，它将应用分为两类：基座应用和子应用。其中，子应用对应需要聚合的应用，基座应用是另外一个单独的应用，用于聚合子应用。</p><p>在基座应用中，我们会维护一个路由注册表 - 每个路由对应一个子应用。基座应用启动以后，当我们切换路由时，如果是一个新的子应用，会动态获取子应用的 js 脚本，然后执行脚本并渲染出相应的页面；如果是一个已经访问过的子应用，那么就会从基座应用的缓存中获取已经缓存的子应用，激活子应用并渲染出对应的页面。</p><h2 id="single-spa-项目模板" tabindex="-1"><a class="header-anchor" href="#single-spa-项目模板" aria-hidden="true">#</a> single-spa 项目模板</h2><p>这里使用 vite+vue 作为基座项目，分别引入 vue2，vue3，react 作为子项目</p>',7),h=e("a",{href:"single-spa%E7%A4%BA%E4%BE%8B"},"文档地址",-1),d=e("br",null,null,-1),_={href:"https://github.com/2290774104/single-spa-template",target:"_blank",rel:"noopener noreferrer"};function u(g,f){const a=n("ExternalLinkIcon");return t(),r("div",null,[p,e("p",null,[h,d,e("a",_,[i("项目地址"),o(a)])])])}const x=s(c,[["render",u],["__file","single-spa基础.html.vue"]]);export{x as default};
